CREATE TABLE IF NOT EXISTS dadosapp.fundalis_ia.pii_access (principal STRING) COMMENT 'Quem está aqui vê PII em claro (controle das máscaras)';;
CREATE OR REPLACE FUNCTION dadosapp.fundalis_ia.pii_liberado() RETURNS BOOLEAN COMMENT 'TRUE se o usuário atual pode ver PII' RETURN current_user() IN (SELECT principal FROM dadosapp.fundalis_ia.pii_access);;
CREATE OR REPLACE FUNCTION dadosapp.fundalis_ia.mask_nome(v STRING) RETURNS STRING RETURN CASE WHEN dadosapp.fundalis_ia.pii_liberado() THEN v WHEN v IS NULL THEN NULL ELSE concat(left(v,1), repeat('*', greatest(char_length(v)-1,3))) END;;
CREATE OR REPLACE FUNCTION dadosapp.fundalis_ia.mask_email(v STRING) RETURNS STRING RETURN CASE WHEN dadosapp.fundalis_ia.pii_liberado() THEN v WHEN v IS NULL THEN NULL ELSE concat(left(v,1), '***@', regexp_extract(v, '@(.*)$', 1)) END;;
CREATE OR REPLACE FUNCTION dadosapp.fundalis_ia.mask_tel(v STRING) RETURNS STRING RETURN CASE WHEN dadosapp.fundalis_ia.pii_liberado() THEN v WHEN v IS NULL THEN NULL ELSE concat(regexp_replace(left(v, char_length(v)-4), '[0-9]', '*'), right(v,4)) END;;
CREATE OR REPLACE FUNCTION dadosapp.fundalis_ia.mask_doc(v STRING) RETURNS STRING RETURN CASE WHEN dadosapp.fundalis_ia.pii_liberado() THEN v WHEN v IS NULL THEN NULL ELSE regexp_replace(v, '[0-9]', '*') END;;
CREATE OR REPLACE FUNCTION dadosapp.fundalis_ia.mask_texto(txt STRING, nome STRING) RETURNS STRING RETURN CASE WHEN dadosapp.fundalis_ia.pii_liberado() THEN txt WHEN txt IS NULL OR nome IS NULL OR trim(nome) = '' THEN txt ELSE regexp_replace(regexp_replace(txt, concat('(?i)', nome), '[cliente]'), concat('(?i)\\b(', array_join(filter(split(nome, ' '), x -> char_length(x) >= 3), '|'), ')\\b'), '[cliente]') END;;
ALTER TABLE dadosapp.fundalis_ia.vendas ALTER COLUMN cliente_nome SET MASK dadosapp.fundalis_ia.mask_nome;;
CREATE TABLE IF NOT EXISTS dadosapp.fundalis_ia.documentos (arquivo STRING, path STRING, tamanho BIGINT, paginas INT, parsed STRING, texto STRING, enviado_por STRING, processado_em TIMESTAMP, titulo STRING, categoria STRING, descricao STRING, atualizado_em TIMESTAMP) COMMENT 'Documentos FICTÍCIOS enviados pelo app e processados com ai_parse_document (v2.0)';;
CREATE TABLE IF NOT EXISTS dadosapp.fundalis_ia.documentos_chunks (chunk_id STRING, arquivo STRING, pagina INT, secao STRING, trecho STRING, processado_em TIMESTAMP) COMMENT 'Trechos (por seção) dos documentos — usados pelo Genie e espelhados com embeddings no Lakebase (agente.doc_chunks)';;
CREATE TABLE IF NOT EXISTS dadosapp.fundalis_ia.perguntas_classificadas (request_id STRING, event_time TIMESTAMP, requester STRING, pergunta STRING, assunto STRING, permitido BOOLEAN, motivo STRING, origem STRING) COMMENT 'Perguntas ao agente extraídas da inference table do AI Gateway e classificadas por assunto pelo guardrail (Opus 4.8)';;
CREATE VOLUME IF NOT EXISTS dadosapp.fundalis_ia.docs COMMENT 'Documentos FICTÍCIOS da base de conhecimento do agente';;
CREATE VOLUME IF NOT EXISTS dadosapp.fundalis_ia.anexos COMMENT 'Anexos (FICTÍCIOS) dos leads — contêm PII, não são indexados no RAG'
